package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateSplit {

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SplitRequest request, Out<ValidSplit> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount to split off must have at most two decimals");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() <= 0) {
            throw new InvalidClaimException("The amount to split off must be more than 0.00");
        }
        body.set(new ValidSplit(request.user(), value));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;

/** A split with its amount parsed. */
public record ValidSplit(String user, BigDecimal amount) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/**
 * Splits an amount (more than 0.00, less than the claim's) off an OPEN claim that is not deferred and whose due-by is not inside a
 * closed period; only the roles the sheet's open permission allows split a claim, as the new claim is theirs to open.
 * The claim keeps the rest of its amount and loses any figure a statement bound it to.
 */
public class ApplySplit {
    public void apply(@Val ValidSplit request, @Val Claim claim, Sheets sheets, Periods periods, Settings settings)
            throws ClaimStatusRefusedException {
        if (!settings.allows(claim.getSheetId(), request.user(), "open")) {
            throw new ClaimStatusRefusedException("Your role may not open a claim, so may not split one");
        }
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusRefusedException("Only an OPEN claim can be split");
        }
        if (claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be split");
        }
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be split");
        }
        if (request.amount().compareTo(claim.getAmount()) >= 0) {
            throw new ClaimStatusRefusedException("The amount to split off must be less than the claim's amount");
        }
        claim.setAmount(claim.getAmount().subtract(request.amount()));
        claim.setStated(false);
        claim.setStatedDue(null);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the split claim and adds the new OPEN claim with the split-off amount, the same date and note, the next
 *  number, opened by the user, its due-by fixed now from the terms in force on the sheet's today, split from the claim, carrying its tags, and a
 *  late entry when the claim is one. */
public class SaveSplit {
    public void save(@Val ValidSplit request, @Val Claim claim, Claims claims, People people, Settings settings,
            ClaimNumbering numbering, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, Out<ClaimSplit> split) {
        claims.save(claim);
        claims.bind(claim);
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        Claim into = claims.add(sheetId, person.getId(), request.amount(), claim.getDate(), claim.getNote(),
                holidays.dueBy(sheetId, claim.getDate(), settings.termsOnCreation(sheetId, person)));
        into.setStatus(ClaimStatus.OPEN);
        into.setNumber(numbering.next(sheetId, into.getPeriodDate()));
        into.setOpenedBy(request.user());
        into.setSplitFrom(claim.getNumber());
        into.setTags(claim.getTags());
        claims.save(into);
        claims.splitFrom(into);
        if (claim.isLateEntry()) {
            // A split is judged by the original claim alone: the new claim is a late entry as it is.
            claims.markLateEntry(into);
        }
        log.record(into, person, request.user());
        split.set(new ClaimSplit(into));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;

public class AuditClaimSplit {
    public void audit(@Val ValidSplit request, @Val Claim claim, @Val ClaimSplit split, People people, Audit audit,
            @Val RollupFigures before, Rollup rollup) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Claim into = split.into();
        audit.recordOnCommit(ClaimAudit.line("CLAIM_SPLIT", request.user(), person, claim, claim.getNumber())
                + " into=" + into.getNumber());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_OPENED", request.user(), person, into, into.getNumber()));
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.claim;

/** The new claim a split made. */
public record ClaimSplit(Claim into) {
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/split: the amount split off the claim, and who splits it. */
public record SplitRequest(String amount, String user) {
}

